fn csv<T: std::fmt::Display>(a: impl IntoIterator<Item = T>) -> String {
    a.into_iter()
        .map(|x| x.to_string())
        .collect::<Vec<_>>()
        .join(",")
}

fn window_stats(values: &[i64], k: usize) -> Vec<(i64, i64)> {
    assert!(k > 0 && k <= values.len());
    let width = k as i64;
    // Sum and sum of squares stay exact; only the reported values are rounded down.
    let mut sum: i64 = values[..k].iter().sum();
    let mut squares: i64 = values[..k].iter().map(|x| x * x).sum();
    let report = |sum: i64, squares: i64| {
        (
            sum.div_euclid(width),
            (width * squares - sum * sum).div_euclid(width * width),
        )
    };
    let mut result = vec![report(sum, squares)];
    for i in k..values.len() {
        sum += values[i] - values[i - k];
        squares += values[i] * values[i] - values[i - k] * values[i - k];
        result.push(report(sum, squares));
    }
    result
}
fn window_means(values: &[i64], k: usize) -> Vec<i64> {
    window_stats(values, k).into_iter().map(|s| s.0).collect()
}
fn window_variances(values: &[i64], k: usize) -> Vec<i64> {
    window_stats(values, k).into_iter().map(|s| s.1).collect()
}

fn main() {
    let result = csv(window_means(&[2, 4, 6, 8, 10], 3));
    println!("{result}");
}

